// Groovy's wardrobe items, drawn in code (round 5 item 3, round 3E item 7):
// the shapes of docs/design/wardrobe-v2/Wardrobe.dc.html and Seasonal.dc.html
// (art/wardrobe.ts, art/seasonal.ts, generated by scripts/gen-art.py), in the
// boards' coordinates mapped onto his body (art/draw.ts), plus the Diamond
// crown, his six-month reward, drawn in the same style.
//
// Coordinates are BotEngine's body space: origin at the body centre, y down,
// R = W × 0.3, rx = 1.14 R, ry = 0.88 R. Items turn a little with his head,
// as the eyes and the growth art do; hats drop on, glasses slide down into
// place and neck items pop in.

import { Ease } from "../core/anim";
import { drawShapes, toBoard, type Art, type Shape } from "./art/draw";
import { SEASONAL_ART } from "./art/seasonal";
import { WARDROBE_ART } from "./art/wardrobe";
import { SLOT_OF } from "./appearance";
import type { Accessory, Outfit } from "./wardrobe";

type Ctx = CanvasRenderingContext2D;

/** Head geometry + the spring lag of the soft parts (−1…1, in head units). */
export interface Head {
  R: number;
  rx: number;
  ry: number;
  yaw: number;
  pitch: number;
  physDx: number;
  physDy: number;
}

export function makeHead(R: number, yaw = 0, pitch = 0, physDx = 0, physDy = 0): Head {
  return { R, rx: R * 1.14, ry: R * 0.88, yaw, pitch, physDx, physDy };
}

/** The board's own Groovy shows through on the seasonal cards: the glints in his eyes. */
function boardEye(s: Shape): boolean {
  return s.f?.toUpperCase() === "#FFFFFF" && /^M(36|60) 61A2 1\.3/.test(s.d);
}

/** The six-month reward: a gold crown with a single pale-blue diamond. */
const DIAMOND_CROWN: Art = {
  front: [
    { d: "M30 33L29 19L38 25L44 12L50 21L56 12L62 25L71 19L70 33Z", f: "#E0B84A", s: "#B8902A", w: 0.8 },
    { d: "M30 29H70V33H30Z", f: "#C99A2E" },
    { d: "M36 31A1.2 1.2 0 1 0 38.4 31A1.2 1.2 0 1 0 36 31ZM61.6 31A1.2 1.2 0 1 0 64 31A1.2 1.2 0 1 0 61.6 31Z", f: "#FFE08A" },
    { d: "M42.8 12A1.4 1.4 0 1 0 45.6 12A1.4 1.4 0 1 0 42.8 12ZM54.4 12A1.4 1.4 0 1 0 57.2 12A1.4 1.4 0 1 0 54.4 12Z", f: "#FFE08A" },
    { d: "M27.8 19A1.3 1.3 0 1 0 30.4 19A1.3 1.3 0 1 0 27.8 19ZM69.6 19A1.3 1.3 0 1 0 72.2 19A1.3 1.3 0 1 0 69.6 19Z", f: "#FFE08A" },
    { d: "M50 19L55 25L50 31L45 25Z", f: "#CFF3FF", s: "#7FD4FF", w: 0.6 },
    { d: "M45 25H55M50 19V31", s: "#FFFFFF", w: 0.4, o: 0.7 },
    { d: "M47.5 22.5L49 21", s: "#FFFFFF", w: 0.7, cap: 1 },
  ],
};

function clean(art: Art): Art {
  const keep = (list?: Shape[]) => list?.filter((s) => !boardEye(s));
  return { behind: keep(art.behind), body: keep(art.body), front: keep(art.front) };
}

/** Every item's art. The cards' eye colours are the board's, not the item's: left out. */
const ITEM_ART: Record<string, Art> = Object.fromEntries([
  ...Object.entries(WARDROBE_ART).map(([id, a]) => [id, clean(a)]),
  ...Object.entries(SEASONAL_ART).map(([id, a]) => [id, clean(a)]),
  ["diamondCrown", DIAMOND_CROWN],
]);

/** An item's shapes (tests). */
export function itemArt(item: Accessory): Art | undefined {
  return ITEM_ART[item];
}

// ── Layers and transitions ────────────────────────────────────────────────────

let scratch: HTMLCanvasElement | null = null;

/**
 * Draws `fn` at `alpha` as one layer, so overlapping parts don't show through
 * each other while an item fades.
 */
function withLayer(ctx: Ctx, alpha: number, fn: (c: Ctx) => void) {
  if (alpha >= 0.999) {
    ctx.save();
    fn(ctx);
    ctx.restore();
    return;
  }
  const W = ctx.canvas.width;
  const Hh = ctx.canvas.height;
  scratch ??= document.createElement("canvas");
  if (scratch.width < W || scratch.height < Hh) {
    scratch.width = Math.max(scratch.width, W);
    scratch.height = Math.max(scratch.height, Hh);
  }
  const s = scratch.getContext("2d");
  if (!s) return;
  s.setTransform(1, 0, 0, 1, 0, 0);
  s.clearRect(0, 0, W, Hh);
  s.setTransform(ctx.getTransform());
  s.save();
  fn(s);
  s.restore();
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha *= alpha;
  ctx.drawImage(scratch, 0, 0, W, Hh, 0, 0, W, Hh);
  ctx.restore();
}

export interface OutfitState {
  /** 0 = gone, 1 = fully on. Animated by the engine. */
  presence: number;
  /** Groovy's mailbox morph: items fade away as he turns into a box. */
  morph: number;
}

/** Turned round (a roll): what sits on his face is behind him. */
function faceTurnedAway(H: Head): boolean {
  return Math.cos(H.yaw) < 0;
}

function layerAlpha(st: OutfitState): number {
  const morphFade = 1 - Math.min(1, Math.max(0, (st.morph - 0.3) / 0.2));
  return morphFade * Math.min(1, st.presence * 2.5);
}

/** The item's way in: hats drop and settle, glasses slide down, neck items pop. */
function arrive(ctx: Ctx, item: Accessory, H: Head, p: number) {
  const posP = Ease.back(p);
  const slot = SLOT_OF[item];
  if (slot === "head") {
    const s = 0.85 + 0.15 * posP;
    ctx.translate(0, -(1 - posP) * H.ry);
    ctx.scale(s, s);
  } else if (slot === "face") {
    ctx.translate(0, -(1 - p) * 0.25 * H.ry);
  } else {
    const s = Math.max(0.001, 0.6 + 0.4 * posP);
    ctx.translate(0, H.ry * 0.85);
    ctx.scale(s, s);
    ctx.translate(0, -H.ry * 0.85);
  }
}

function drawItem(ctx: Ctx, art: Art, H: Head, layers: readonly ("behind" | "body" | "front")[]) {
  toBoard(ctx, H.rx, H.ry, Math.sin(H.yaw) * H.rx * 0.35);
  for (const l of layers) drawShapes(ctx, art[l]);
}

/**
 * The parts behind Groovy's body. `ctx` is in body space (translated to the body
 * centre, tilted and squashed exactly like the body).
 */
export function drawOutfitBehind(ctx: Ctx, outfit: Outfit, H: Head, st: OutfitState) {
  if (outfit === "none") return;
  const art = ITEM_ART[outfit];
  const alpha = layerAlpha(st);
  if (!art || alpha <= 0.005) return;
  const face = SLOT_OF[outfit] === "face";
  // Turned away, his glasses are behind him; anything that is always behind stays there.
  const layers = face && faceTurnedAway(H) ? (["behind", "body", "front"] as const) : (["behind"] as const);
  if (!layers.some((l) => art[l]?.length)) return;
  ctx.save();
  arrive(ctx, outfit, H, st.presence);
  withLayer(ctx, alpha, (l) => drawItem(l, art, H, layers));
  ctx.restore();
}

/** The parts in front of Groovy, drawn after the body and the eyes. */
export function drawOutfitFront(ctx: Ctx, outfit: Outfit, H: Head, st: OutfitState) {
  if (outfit === "none") return;
  const art = ITEM_ART[outfit];
  if (!art || (SLOT_OF[outfit] === "face" && faceTurnedAway(H))) return;
  const alpha = layerAlpha(st);
  if (alpha <= 0.005) return;
  ctx.save();
  arrive(ctx, outfit, H, st.presence);
  // The board puts glasses that hide the eyes under them; on him they go over.
  withLayer(ctx, alpha, (l) => drawItem(l, art, H, ["body", "front"]));
  ctx.restore();
}

// ── Wardrobe icons ────────────────────────────────────────────────────────────

/** The board's body: a 72×62 rounded rect at (14, 30). */
const ICON_BODY = "M36 30H64A22 22 0 0 1 86 52V70A22 22 0 0 1 64 92H36A22 22 0 0 1 14 70V52A22 22 0 0 1 36 30Z";
let iconBody: Path2D | null = null;

/** A little Groovy wearing `item`, as on the boards, in a `size`×`size` icon. */
function iconGroovy(ctx: Ctx, size: number, item: Accessory) {
  const art = ITEM_ART[item];
  // The boards' view, -8…104 high: hats reach up to about y -4, neck items down to 100.
  const k = size / 112;
  ctx.save();
  ctx.translate(size / 2 - 50 * k, 8 * k);
  ctx.scale(k, k);
  drawShapes(ctx, art?.behind);
  iconBody ??= new Path2D(ICON_BODY);
  const g = ctx.createLinearGradient(70, 30, 30, 92);
  g.addColorStop(0, "#F1F3F5");
  g.addColorStop(1, "#C6C9CF");
  ctx.fillStyle = g;
  ctx.fill(iconBody);
  ctx.fillStyle = "#1A1412";
  for (const ex of [38, 62]) {
    ctx.beginPath();
    ctx.ellipse(ex, 62, 5.5, 4, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.save();
  ctx.clip(iconBody);
  drawShapes(ctx, art?.body, "clipped");
  drawShapes(ctx, art?.front, "clipped");
  ctx.restore();
  drawShapes(ctx, art?.body, "free");
  drawShapes(ctx, art?.front, "free");
  ctx.restore();
}

/** One wardrobe button's picture; "none" is a crossed-out circle. */
export function drawWardrobeIcon(ctx: Ctx, size: number, selection: Outfit) {
  ctx.clearRect(0, 0, size, size);
  if (selection === "none") {
    const r = 6.5;
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.strokeStyle = "#454850";
    ctx.lineWidth = 1.4;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.82, 0, Math.PI * 2);
    ctx.moveTo(-r * 0.56, r * 0.56);
    ctx.lineTo(r * 0.56, -r * 0.56);
    ctx.stroke();
    ctx.restore();
    return;
  }
  iconGroovy(ctx, size, selection);
}
